    // Ratio metric undefined when a level pair sums to zero.
    let zsum = [-1.0, 1.0, 1.0, -1.0];
    assert!(kripp_alpha(&zsum, 2, 2, "ratio")
        .unwrap_err()
        .contains("ratio"));
